CREATE TABLE phone_data (person text, phone text, private boolean);

-- rules.sgml:2055
CREATE VIEW phone_number AS
    SELECT person, CASE WHEN NOT private THEN phone END AS phone
    FROM phone_data;

-- rules.sgml:2055
